import {resolveMorale} from './morale.js';
import {StudioMusic} from './music.js';
import {SYMBOLS,LINES,MODES,CONFIG} from './config.js';
import {makeGrid,regular,lineWins,collection,triggered} from './engine.js';
import {JOKES,WIN_NAMES} from './jokes.js';
const $=id=>document.getElementById(id),fmt=n=>(n/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
let balance=CONFIG.initialCredits,wagerIndex=1,locked=false,state='idle',free=0,modes=[],bonusTotal=0,awarded=0,forced=null,round=0,lastJoke=0,jokeQueue=[],muted=true,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,skip=false,audio=null,musicTimer=null,willToDesign=28;
const soundtrack=new StudioMusic();
let grid=makeGrid(CONFIG.wagers[wagerIndex]);
// Opening composition is an unpaid display, not a resolved round.
grid[0][0]={id:'pen'};grid[1][0]={id:'coffee'};grid[2][0]={id:'folder'};grid[3][0]={id:'logo'};grid[4][0]={id:'wild'};grid[4][2]={id:'collect',mult:1};
function artStyle(i){return `background-position:${(i%4)*100/3}% ${Math.floor(i/4)*50}%`}
function symbolName(s){return SYMBOLS.find(x=>x.id===s.id)?.name??(s.id==='invoice'?`Invoice ${fmt(s.value)} credits`:s.id==='pin'?MODES[s.mode].name:s.id==='effect'?`Effects ×${s.mult}`:s.id==='rush'?`Rush Fee ×${s.mult}`:'Accounts Payable')}
function cellHTML(s,c,r){const sym=SYMBOLS.find(x=>x.id===s.id);let art=sym?.art??({invoice:9,collect:10,rush:11})[s.id];let content=art!==undefined?`<div class="symbol-art" style="${artStyle(art)}"></div>`:s.id==='pin'?`<div class="comment-pin ${s.mode} ${MODES[s.mode].color}">${{logo:'↗',tiny:'+',pop:'✳'}[s.mode]}</div>`:`<div class="effect-symbol">×${s.mult}</div>`;
if(s.id==='invoice')content+=`<b class="special-value">${fmt(s.value)}</b>`;if(s.id==='rush')content+=`<b class="special-value">×${s.mult}</b>`;
return `<div class="cell" data-c="${c}" data-r="${r}" data-id="${s.id}" aria-label="Reel ${c+1}, row ${r+1}: ${symbolName(s)}">${content}<span class="symbol-label">${s.id==='invoice'?'FREELANCE INVOICE':s.id==='pin'?'CLIENT COMMENT':s.id==='effect'?'MAKE IT POP':s.id==='rush'?'RUSH FEE':s.id==='collect'?'ACCOUNTS PAYABLE':sym.name}</span></div>`}
function render(){ $('reels').innerHTML=grid.map((col,c)=>`<div class="reel" id="reel-${c}">${col.map((s,r)=>cellHTML(s,c,r)).join('')}</div>`).join('');}
function status(next,text){state=next;$('state-badge').textContent='● '+({idle:'READY',spinning:'SPINNING',evaluating:'PROOFING',collecting:'PAYMENT',entering:'FEEDBACK',bonus:'FREE SPIN',returning:'SAVED'})[next];$('event-text').textContent=text;}
function update(){ $('balance').textContent=fmt(balance);$('wager').textContent=fmt(CONFIG.wagers[wagerIndex]);$('spin').disabled=locked||(balance<CONFIG.wagers[wagerIndex]&&!free);$('less').disabled=locked||free>0||wagerIndex===0;$('more').disabled=locked||free>0||wagerIndex===CONFIG.wagers.length-1;$('reset').disabled=locked||free>0;document.querySelectorAll('[data-force]').forEach(b=>b.disabled=locked||free>0);$('bonus-count').textContent=free?`${free} FREE SPINS`:'BASE GAME';$('spin').innerHTML=`<span class="spin-icon">↻</span><span>${free?'NEXT FREE REVISION':'ANOTHER REVISION'}<small>${free?'FREE SPIN · SPACEBAR':'SPIN · SPACEBAR'}</small></span>`;document.querySelectorAll('[data-info]').forEach(b=>b.classList.toggle('active',modes.includes(b.dataset.info)));$('mode-label').textContent=modes.length===3?'DESIGN BY COMMITTEE':modes.length?modes.map(m=>MODES[m].short.toUpperCase()).join(' + '):'20 PAYLINES / 5 REELS / NO WORK–LIFE BALANCE';document.querySelector('.application').classList.toggle('committee',modes.length===3);document.querySelector('.application').classList.toggle('tiny-active',modes.includes('tiny'));$('committee-comments').hidden=modes.length!==3;document.querySelector('.application').classList.toggle('pop-active',modes.includes('pop'));$('portrait-frame').classList.toggle('optimistic',round<5&&!reduced);}
async function wait(ms){if(reduced)return;const end=Date.now()+ms;while(Date.now()<end&&!skip)await new Promise(r=>setTimeout(r,40));}
function tone(freq=400,duration=.08,type='sine',volume=.025,delay=0){if(muted||document.hidden)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime+delay);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+delay+duration);o.connect(g);g.connect(audio.destination);o.start(audio.currentTime+delay);o.stop(audio.currentTime+delay+duration);}catch{}}
function noise(type){if(muted||document.hidden)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();let duration=type==='slurp'?.23:.045;const b=audio.createBuffer(1,audio.sampleRate*duration,audio.sampleRate);const d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);const s=audio.createBufferSource(),f=audio.createBiquadFilter(),g=audio.createGain();s.buffer=b;f.type=type==='slurp'?'lowpass':'highpass';f.frequency.value=type==='slurp'?600:2500;g.gain.value=.035;s.connect(f);f.connect(g);g.connect(audio.destination);s.start();}catch{}}
function cue(kind){if(kind==='spin'){noise('clack');tone(160,.08,'sawtooth',.009);}else if(kind==='stop'){noise('clack');tone(120,.04,'triangle',.02);}else if(kind==='collect'){[330,440,660,880].forEach((f,i)=>tone(f,.18,'sine',.03,i*.09));}else if(kind==='message'){tone(880,.1,'sine',.015);tone(660,.1,'sine',.015,.12);}else if(kind==='logo'){[220,330,440].forEach((f,i)=>tone(f,.25,'sawtooth',.009,i*.14));}else if(kind==='tiny'){for(let i=0;i<5;i++)tone(700+i*60,.07,'square',.008,i*.09);}else if(kind==='pop'){[523,659,784,1047].forEach((f,i)=>tone(f,.3,'triangle',.025,i*.1));}}
function joke(force=false){if(!force&&Date.now()-lastJoke<9000)return;lastJoke=Date.now();if(!jokeQueue.length)jokeQueue=JOKES.slice(1).sort(()=>Math.random()-.5);$('joke').textContent='“'+jokeQueue.pop()+'”';cue('message');$('client-message').animate?.([{transform:'translateY(5px) rotate(1deg)'},{transform:'translateY(0) rotate(1deg)'}],{duration:reduced?0:250});}
function react(big=false){const frame=$('portrait-frame');frame.classList.remove('reacting','meltdown');void frame.offsetWidth;frame.classList.add(big?'meltdown':'reacting');$('inbox').textContent=127+round;renderMorale();$('committee-comments').hidden=modes.length!==3;$('mood').textContent=modes.length===3?'TERRIFYINGLY FOCUSED.':willToDesign>=70?'IDEAS ARE HAPPENING.':willToDesign>=40?'I STILL HAVE IT.':willToDesign>=20?'STILL PROFESSIONAL.':'CREATIVELY UNAVAILABLE.';$('layer-1').textContent=round<5?'final_for_real':`final_PLEASE_v${27+round}`;$('layer-2').textContent=modes.includes('tiny')?`copy_of_copy_${round}`:'final_final';if(round%4===0)noise('slurp');}
async function animateSpin(next){$('skip').hidden=false;for(let c=0;c<5;c++)$('reel-'+c).classList.add('rolling');let ticks=0;const timer=setInterval(()=>{if(reduced||skip)return;for(let c=0;c<5;c++)if($('reel-'+c).classList.contains('rolling'))$('reel-'+c).innerHTML=Array.from({length:4},(_,r)=>cellHTML(regular(),c,r)).join('');if(ticks++%3===0)noise('clack');},90);try{await wait(550);for(let c=0;c<5;c++){grid[c]=next[c];const reel=$('reel-'+c);reel.innerHTML=grid[c].map((s,r)=>cellHTML(s,c,r)).join('');reel.classList.remove('rolling');reel.classList.add('stopped');cue('stop');await wait(155);}}finally{clearInterval(timer);grid=next;render();document.body.classList.remove('is-spinning');}}
function cellsFor(coords,cls){coords.forEach(({c,r})=>document.querySelector(`.cell[data-c="${c}"][data-r="${r}"]`)?.classList.add(cls));}
function trails(col){if(reduced||skip||!col.collectors.length)return;const target=document.querySelector(`.cell[data-c="4"][data-r="${col.collectors[0].r}"]`).getBoundingClientRect();col.invoices.forEach(s=>{const a=document.querySelector(`.cell[data-c="${s.c}"][data-r="${s.r}"]`).getBoundingClientRect(),el=document.createElement('i');el.className='collection-trail';el.style.left=a.x+a.width/2+'px';el.style.top=a.y+a.height/2+'px';el.style.setProperty('--dx',target.x+target.width/2-a.x-a.width/2+'px');el.style.setProperty('--dy',target.y+target.height/2-a.y-a.height/2+'px');document.body.append(el);setTimeout(()=>el.remove(),750);});}
async function countWin(value){const start=performance.now(),dur=reduced||skip?0:700;await new Promise(resolve=>{function frame(t){const progress=dur?Math.min(1,(t-start)/dur):1;$('last-win').textContent=fmt(Math.round(value*progress));if(progress<1&&!skip)requestAnimationFrame(frame);else{$('last-win').textContent=fmt(value);resolve();}}requestAnimationFrame(frame);});}
function renderMorale(){
  $('will-label').textContent=willToDesign+'%';$('will-bar').style.width=willToDesign+'%';
  $('will-meter').setAttribute('aria-valuenow',String(willToDesign));
  $('will-bar').style.background=willToDesign>=50?'var(--lime)':'var(--orange)';
}
function moraleResult(win,wager,ledger){
  const before=willToDesign,result=resolveMorale(before,win,wager);willToDesign=result.value;renderMorale();
  ledger.willToDesign={before,after:willToDesign,change:result.change};
  $('morale-gain').textContent=win?(result.change?`+${result.change}% HOPE RESTORED`:'100% · CREATIVE RENAISSANCE'):'−2% · ANOTHER EMAIL';
  $('morale-gain').classList.toggle('positive',win>0);
  const stress=document.querySelector('.stress');stress.classList.remove('restored');void stress.offsetWidth;if(win)stress.classList.add('restored');
  if(win){$('mood').textContent=willToDesign>=70?'I AM A CREATIVE GENIUS.':'MAYBE THIS IS WORTH IT.';$('coffee-note').textContent='Payment received. A small reason to believe.';}
}
async function showPaylines(wins){
  const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');
  svg.setAttribute('viewBox','0 0 500 400');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-hidden','true');svg.classList.add('payline-overlay');$('reels').append(svg);
  for(const win of wins.slice(0,4)){
    if(skip)break;
    document.querySelectorAll('.line-focus').forEach(e=>e.classList.remove('line-focus'));
    cellsFor(win.rows.slice(0,win.count).map((r,c)=>({c,r})),'line-focus');
    const line=document.createElementNS(ns,'polyline');line.setAttribute('points',win.rows.slice(0,win.count).map((r,c)=>`${c*100+50},${r*100+50}`).join(' '));svg.replaceChildren(line);
    $('result-label').textContent=`LINE ${String(win.line+1).padStart(2,'0')} · ${win.count} MATCH · +${fmt(win.amount)} cr`;
    tone(440+win.count*65,.13,'triangle',.025);await wait(480);
  }
  svg.remove();document.querySelectorAll('.line-focus').forEach(e=>e.classList.remove('line-focus'));
}
function confetti(tier){
  if(reduced||skip)return;
  const host=$('win-particles');host.replaceChildren();
  for(let i=0;i<(tier>=2?44:18);i++){const bit=document.createElement('i');bit.style.cssText=`--x:${Math.random()*100}%;--drift:${(Math.random()-.5)*180}px;--turn:${Math.random()*700-350}deg;--delay:${Math.random()*.45}s;--color:${['#d0ed59','#f48fb7','#ffa166','#f4f1e7'][i%4]}`;host.append(bit);}
}
async function celebrate(amount,wager){
  const ratio=amount/wager,index=ratio>=500?4:ratio>=100?3:ratio>=20?2:ratio>=5?1:0;
  $('result-label').textContent=WIN_NAMES[index]+' · +'+fmt(amount)+' cr';
  $('win-title').textContent=WIN_NAMES[index];$('win-amount').textContent='+'+fmt(amount)+' cr';
  $('win-banner').hidden=false;$('win-banner').dataset.tier=index;
  document.querySelector('.application').classList.add('winning');$('portrait-frame').classList.add('celebrating');
  confetti(index);[523.25,659.25,783.99].forEach((f,i)=>tone(f,.28,'triangle',.022,i*.09));
  if(index>=2){$('celebration-title').textContent=WIN_NAMES[index];$('celebration-value').textContent='+'+fmt(amount)+' cr';$('celebration').hidden=false;$('portrait-frame').classList.add('peaceful');cue('pop');}
  await wait(index>=2?3200:index===1?1700:1150);
  $('celebration').hidden=true;$('portrait-frame').classList.remove('peaceful','celebrating');document.querySelector('.application').classList.remove('winning');$('win-particles').replaceChildren();
  if(index>=2)joke();
}
function forceGrid(next,wager,force){if(['all','logo','tiny','pop'].includes(force)){const keys=force==='all'?Object.keys(MODES):[force];for(const m of keys)next[MODES[m].reel][1]={id:'pin',mode:m};}if(force==='collect'||force==='huge'){next[0][0]={id:'invoice',value:force==='huge'?wager*500:wager*2};next[2][2]={id:'invoice',value:force==='huge'?wager*500:wager*3};next[4]=next[4].map(s=>['collect','rush'].includes(s.id)?{id:'pen'}:s);next[4][1]={id:'rush',mult:force==='huge'?1:3};}return next;}
async function spin(){if(locked||$('help-dialog').open||$('dev-dialog').open)return;const wager=CONFIG.wagers[wagerIndex],isBonus=free>0;if(!isBonus&&balance<wager)return;locked=true;skip=false;round++;$('win-banner').hidden=true;$('morale-gain').textContent='';document.body.classList.add('is-spinning');const before=balance,force=forced;forced=null;$('forced-label').textContent='No outcome forced.';if(isBonus)free--;else balance-=wager;const currentModes=[...modes];const ledger={round,type:isBonus?'free spin':'base spin',forced:force??false,wager:fmt(wager),balanceBefore:fmt(before),debit:isBonus?'0.00':fmt(wager),activeModes:currentModes};$('last-win').textContent='0.00';$('result-label').textContent=isBonus?'Revision included. Emotional cost extra.':'Checking for new feedback…';update();status('spinning',isBonus?`${free+1} free revisions left. Deep breath.`:'Opening the client’s latest email…');cue('spin');
try{await animateSpin(forceGrid(makeGrid(wager,currentModes),wager,force));react(currentModes.length===3);status('evaluating','Checking 20 paylines, left to right.');const wins=lineWins(grid,wager),lineTotal=wins.reduce((a,w)=>a+w.amount,0);ledger.paylines=wins.map(w=>({line:w.line+1,symbol:w.id,count:w.count,credits:fmt(w.amount)}));if(wins.length){cellsFor(wins.flatMap(w=>w.rows.slice(0,w.count).map((r,c)=>({c,r}))),'win');$('result-label').textContent=`${wins.length} PAYLINE${wins.length===1?'':'S'} · +${fmt(lineTotal)} cr`;tone(523,.15);await showPaylines(wins);}else await wait(180);
const col=collection(grid);if(col.amount){status('collecting',`Invoices ${fmt(col.subtotal)} cr → Accounts Payable`);cellsFor(col.invoices,'collected');trails(col);cue('collect');await wait(800);const collector=col.collectors[0];if(collector.mult>1){status('collecting',`Rush Fee: ${fmt(col.subtotal)} × ${collector.mult} = ${fmt(col.subtotal*collector.mult)} cr`);cellsFor(col.collectors,'collected');if(currentModes.includes('logo')){document.querySelector('.application').classList.add('logo-grow');$('light-logo').classList.add('lit');cue('logo');react(true);}await wait(1000);}if(col.effectMultiplier>1){status('collecting',`Effects: ×${col.effectMultiplier} → ${fmt(col.amount)} cr collected`);cellsFor(col.effects,'collected');cue('pop');react(true);await wait(1000);}else status('collecting',`Payment received: ${fmt(col.amount)} cr. Unprecedented.`);await wait(450);}
ledger.collection={invoiceSubtotal:fmt(col.subtotal),collectorMultipliers:col.collectors.map(x=>x.mult),effectMultiplier:col.effectMultiplier,payout:fmt(col.amount)};const win=lineTotal+col.amount;balance+=win;if(isBonus)bonusTotal+=win;ledger.payout=fmt(win);ledger.balanceAfter=fmt(balance);moraleResult(win,wager,ledger);await countWin(win);update();if(win)await celebrate(win,wager);else $('result-label').textContent=col.invoices.length?'Invoices outstanding. A collector must land to get paid.':'No payment this round. Exposure remains priceless.';
let triggers=force&&['all','logo','tiny','pop'].includes(force)?(force==='all'?Object.keys(MODES):[force]):triggered(grid);grid.flat().filter(s=>s.id==='pin').forEach(s=>$('light-'+s.mode).classList.add('lit'));if(triggers.length){if(!isBonus){modes=triggers;free=CONFIG.freeSpins;awarded=free;bonusTotal=0;ledger.bonusAward=free;}else{modes=[...new Set([...modes,...triggers])];const extra=Math.min(CONFIG.retriggerSpins,CONFIG.maxFreeSpins-awarded);free+=extra;awarded+=extra;ledger.retriggerAward=extra;}status('entering',modes.length===3?'DESIGN BY COMMITTEE. Everyone has notes.':modes.map(x=>MODES[x].name).join(' + '));update();for(const m of triggers){cue(m);await wait(250);}if(modes.includes('tiny')){$('coffee-note').textContent='Coffee count: concerning. Collector: guaranteed.';$('layer-2').textContent='revision_of_revision_of_revision';}await wait(1500);}
if(isBonus&&free===0){status('returning',`Project exported. Bonus total: ${fmt(bonusTotal)} cr.`);$('result-label').textContent=`FREE REVISIONS COMPLETE · ${fmt(bonusTotal)} cr won`;await wait(1000);modes=[];awarded=0;status('idle',`Bonus finished: ${fmt(bonusTotal)} cr. Back to the inbox.`);}else if(free)status('bonus',`${free} free spins remain · bonus winnings ${fmt(bonusTotal)} cr`);else status('idle',balance<wager?'Out of fictional credits. Reset in DEV / REVIEW.':'Ready for another revision. Spacebar to spin.');ledger.freeSpinsRemaining=free;$('ledger').textContent=JSON.stringify(ledger,null,2);joke();
}catch(error){console.error(error);status('idle','Round interrupted. Review the ledger before continuing.');$('ledger').textContent=JSON.stringify({...ledger,error:String(error),balanceAfter:fmt(balance)},null,2);}finally{locked=false;skip=false;document.body.classList.remove('is-spinning');$('win-particles').replaceChildren();document.querySelector('.application').classList.remove('winning');$('portrait-frame').classList.remove('celebrating');$('skip').hidden=true;$('celebration').hidden=true;$('portrait-frame').classList.remove('peaceful');document.querySelector('.application').classList.remove('logo-grow');for(const m of Object.keys(MODES))$('light-'+m).classList.remove('lit');update();}}
$('spin').onclick=spin;$('less').onclick=()=>{if(!locked&&!free){wagerIndex=Math.max(0,wagerIndex-1);update();}};$('more').onclick=()=>{if(!locked&&!free){wagerIndex=Math.min(CONFIG.wagers.length-1,wagerIndex+1);update();}};$('skip').onclick=$('celebration-skip').onclick=()=>{skip=true;};
$('sound').onclick=async()=>{
  muted=!muted;$('sound').textContent=muted?'SOUND OFF':'SOUND ON';$('sound').setAttribute('aria-pressed',String(!muted));$('sound').setAttribute('aria-label',muted?'Enable sound and background music':'Mute sound and background music');
  if(muted){soundtrack.stop();audio?.suspend();}else{try{await soundtrack.start();await audio?.resume();cue('message');}catch{muted=true;soundtrack.stop();$('sound').textContent='SOUND OFF';$('sound').setAttribute('aria-pressed','false');$('event-text').textContent='Audio unavailable. You can keep playing silently.';}}
};
$('music-volume').addEventListener('input',e=>{soundtrack.setVolume(Number(e.target.value)/100);$('music-level').textContent=e.target.value+'%';});
document.addEventListener('visibilitychange',()=>{if(document.hidden){soundtrack.stop();audio?.suspend();}else if(!muted){soundtrack.start().catch(()=>{});audio?.resume();}});
function setMotion(){document.body.classList.toggle('reduced',reduced);$('motion').textContent='REDUCED MOTION: '+(reduced?'ON':'OFF');$('motion').setAttribute('aria-pressed',String(reduced));update();} $('motion').onclick=()=>{reduced=!reduced;setMotion();};
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!['BUTTON','INPUT','SELECT','TEXTAREA','A'].includes(e.target.tagName)&&!$('help-dialog').open&&!$('dev-dialog').open){e.preventDefault();if(locked)skip=true;else spin();}});
function openDialog(id){$(id).showModal();}document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('help').onclick=()=>{showHelp('rules');openDialog('help-dialog');};$('dev').onclick=()=>{update();openDialog('dev-dialog');};document.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>{showHelp('rules');openDialog('help-dialog');});document.querySelectorAll('[data-force]').forEach(b=>b.onclick=()=>{if(locked||free)return;forced=b.dataset.force;$('forced-label').textContent=`Next spin: ${b.textContent}.`;$('dev-dialog').close();status('idle',`REVIEW QUEUED · ${b.textContent}. Press spin.`);});$('reset').onclick=()=>{if(locked||free)return;balance=CONFIG.initialCredits;$('ledger').textContent='Fictional balance reset to 1,000.00 cr.';update();};
const helpRules=`<p class="notice"><strong>Fictional credits. Real creative fatigue.</strong> No deposits, withdrawals, prizes, or cash value.</p><h3>The working day, unfortunately</h3><p>Choose a wager and spin. All 20 fixed paylines are included. Match 3–5 identical paying symbols on consecutive reels starting at the far left. Only the highest award on each line pays; different lines add together. CMD+Z substitutes only for the eight regular symbols and itself, never invoices, collectors, comment pins, or effect multipliers.</p><h3>Getting paid</h3><p>Invoices land on reels 1–4. Accounts Payable on reel 5 collects their total. Rush Fee collects that same total × its displayed multiplier (1×, 2×, 3×, 5× or 10×). Only one collector can land per spin. Without a collector, invoices pay nothing and do not carry over. Collection awards are added to line wins.</p><h3>Three ways to lose your evening</h3><ul><li><strong>JUST ONE TINY CHANGE · pink + · reel 2:</strong> guarantees an Accounts Payable or Rush Fee collector on every free spin.</li><li><strong>MAKE THE LOGO BIGGER · lime ↗ · reel 3:</strong> Rush Fee becomes more likely and always carries 2×, 3×, 5× or 10×. The growing logo is a visual reaction; it does not change line payouts.</li><li><strong>CAN YOU MAKE IT POP? · orange ✳ · reel 4:</strong> 2×, 3× or 5× effect symbols may land on reels 1–4. Multiply all visible effect multipliers together, then apply the result to collection winnings only.</li></ul><p>A comment pin has a 22% chance to activate its path. Multiple activated paths combine. Landing all three colors together guarantees <strong>DESIGN BY COMMITTEE</strong>, with all three active. Each initial bonus grants <strong>10 free spins</strong>. Play each free spin with the spin button; the wager stays locked.</p><p>During a bonus, successful pin activations add any newly activated paths and award <strong>3 extra spins once per round</strong>, capped at 30 total awarded spins for that bonus. At the cap, paths can still be added. All active paths persist until the bonus ends. Free spins deduct no credits.</p><h3>One thing at a time</h3><p>Line awards → invoice subtotal → Rush Fee → effect multipliers → total credited → bonus entry or retrigger. Multipliers never multiply line wins. Credits use integer hundredths internally; each line award rounds to the nearest 0.01 cr. The ledger in DEV / REVIEW records every resolved round.</p><h3>Controls</h3><p>Spacebar spins, or skips an active animation. Sound is off initially. SOUND ON enables an original looping late-night track and game effects; MUSIC adjusts only the background track. Audio pauses in hidden tabs. Every payout restores Will to Design (6–45 points depending on win size, capped at 100%); a round without a payout costs 2 points, with a floor of 2%. This mood meter never affects payouts or odds. Reduced motion follows your device preference until changed. Help and review dialogs support Escape. If credits run out, reset the fictional balance in the review panel.</p>`;
function showHelp(tab){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let html='';if(tab==='rules')html=helpRules;if(tab==='paytable')html=`<p>A line stake is total wager ÷ 20. Values below multiply the line stake. At the current ${fmt(CONFIG.wagers[wagerIndex])} cr wager, each line stake is ${fmt(CONFIG.wagers[wagerIndex]/20)} cr.</p><table><thead><tr><th>SYMBOL</th><th>3 MATCH</th><th>4 MATCH</th><th>5 MATCH</th></tr></thead><tbody>${SYMBOLS.map(s=>`<tr><td><i class="table-art" style="${artStyle(s.art)}"></i>${s.name}</td>${s.pay.map(p=>`<td>${p}×</td>`).join('')}</tr>`).join('')}</tbody></table><p>All-wild lines use the CMD+Z paytable. A line pays its highest matching award only. Special symbols never form line wins.</p><h3>Invoices & collection</h3><p>Invoices: 0.3×, 0.5×, 1×, 2×, 5× or 10× total wager. Rush Fee: 1×, 2×, 3×, 5× or 10× collection multiplier. Pop effects: 2×, 3× or 5×, multiplied together. Invoices must be collected to pay.</p>`;if(tab==='lines')html=`<p>20 fixed paylines. Each starts on reel 1 and pays from left to right. Highlighted squares show the path, with rows numbered top to bottom in the underlying configuration.</p><div class="line-grid">${LINES.map((rows,i)=>`<div class="line-example" aria-label="Line ${i+1}, rows ${rows.map(r=>r+1).join(', ')}"><small>LINE ${String(i+1).padStart(2,'0')}</small>${Array.from({length:20},(_,n)=>`<i class="${rows[n%5]===Math.floor(n/5)?'on':''}"></i>`).join('')}</div>`).join('')}</div>`;$('help-content').innerHTML=html;}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>showHelp(b.dataset.tab));render();setMotion();update();
